const fs = require('fs');
const path = require('path');

// ============================================================
// generar_472_nombres_reales.js
// ============================================================
// EL PROBLEMA
// El chat decia "no tengo eso registrado" sobre la edad, el estado
// reproductivo y la raza, aunque estuvieran en la base.
//
// LA CAUSA
// Pedi la columna 'esterilizado', que NO EXISTE. La tabla mascotas
// tiene 'castrado' y 'estado_reproductivo'.
//
// Una columna inexistente hace fallar TODA la consulta, asi que
// tampoco llegaban la raza ni la fecha de nacimiento — que si existen.
//
// Y la tabla 'celos' tampoco existe: el seguimiento reproductivo vive
// como una columna del perfil, no como tabla aparte.
//
// LOS NOMBRES REALES, confirmados contra la base:
//   castrado, estado_reproductivo, alergias, color, microchip,
//   peso_actual, alimentacion_tipo, alimentacion_marca, veterinaria,
//   tamano_esperado, seguimiento_reproductivo
//
// SE PREFIERE estado_reproductivo sobre castrado cuando existe: dice
// mas que un si/no ("esterilizada" en vez de "esterilizado/a").
//
// Y SE APROVECHA de traer lo que no habia pedido: la marca del
// alimento, la veterinaria de cabecera y el tamaño esperado.
//
//   Tú: ¿cuáles son sus datos?
//   Chiqui: Lucy:
//           · Raza: Siamés
//           · Edad: 6 años y 5 meses
//           · Sexo: Hembra, esterilizada
//           · Alimento: Royal Canin
//           · Veterinaria: Clínica San Bernardo
//           · ⚠️ Alergia: Pollo
//           · Peso: 4.2 kg (20 ago)
//
// LA LECCION, otra vez: nunca asumir el nombre de una columna. Debi
// pedirte el esquema antes de escribir el script 467.
//
// REQUISITO: script 471 desplegado.
//
// Si algo no calza, ABORTA sin escribir NADA.
// ============================================================

const RUTA_CHAT = 'components/ChiquiChat.tsx';
const RUTA_FLOT = 'components/ChiquiFlotante.tsx';
const CHAT_B64 = '';
const FLOT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico NINGUN archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const dChat = path.join(process.cwd(), RUTA_CHAT);
const dFlot = path.join(process.cwd(), RUTA_FLOT);
for (const [r, d] of [[RUTA_CHAT, dChat], [RUTA_FLOT, dFlot]]) {
  if (!fs.existsSync(d)) abortar('no se encontro ' + r + '.');
}

const actualFlot = fs.readFileSync(dFlot, 'utf8');
if (actualFlot.includes('estado_reproductivo')) {
  abortar('los nombres ya estan corregidos. Parece que este script ya se corrio.');
}
if (!actualFlot.includes('let perfilM')) {
  abortar('falta el script 471. Correlo primero.');
}

const chat = Buffer.from(CHAT_B64, 'base64').toString('utf8');
const flot = Buffer.from(FLOT_B64, 'base64').toString('utf8');

// La columna que NO existe no puede volver a pedirse.
// Se busca en el SELECT del perfil, no en cualquier parte: la palabra
// "esterilizado/a" aparece en textos de respuesta y no es la columna.
const marcaSelect = ".select('raza";
const posSelect = flot.indexOf(marcaSelect);
if (posSelect === -1) {
  abortar('no encontre el select del perfil en el contenido nuevo. Script corrupto.');
}
const selectPerfil = flot.slice(posSelect, posSelect + 300);
if (selectPerfil.includes('esterilizado')) {
  abortar("el select del perfil sigue pidiendo 'esterilizado', que no existe. Script corrupto.");
}
for (const r of ['estado_reproductivo', 'castrado', 'alimentacion_marca', 'veterinaria']) {
  if (!flot.includes(r)) abortar('el flotante nuevo no pide [' + r + ']. Script corrupto.');
}
console.log('  OK  el flotante usa los nombres reales');

// La tabla que no existe tampoco.
if (flot.includes("from('celos')")) {
  abortar("el flotante sigue consultando la tabla 'celos', que no existe.");
}
console.log('  OK  ya no consulta la tabla celos');

for (const r of ['estadoReproductivo', 'castrado: boolean | null', 'p.alimentacion', 'p.veterinaria']) {
  if (!chat.includes(r)) abortar('el chat nuevo no incluye [' + r + ']. Script corrupto.');
}
console.log('  OK  el chat sabe leer los campos nuevos');

fs.writeFileSync(dChat, chat, 'utf8');
console.log('');
console.log('OK: ' + RUTA_CHAT);
fs.writeFileSync(dFlot, flot, 'utf8');
console.log('OK: ' + RUTA_FLOT);
console.log('');
console.log('Prueba con "¿cuales son sus datos?", "¿cuantos años tiene?" y');
console.log('"¿esta esterilizada?".');
console.log('');
console.log('Listo.');
